<?php require_once __DIR__.'/includes/functions.php'; $stmt=db()->prepare("SELECT a.*,d.name destination_name FROM attractions a JOIN destinations d ON d.id=a.destination_id WHERE a.slug=? AND a.status='active'"); $stmt->execute([$_GET['slug']??'']); $a=$stmt->fetch(); if(!$a){http_response_code(404);exit('Attraction not found');} $title=$a['name']; include __DIR__.'/includes/header.php'; ?>
<main class="container py-5"><a href="attractions.php">&larr; All attractions</a><div class="row g-5 mt-1"><div class="col-lg-6"><?php if($a['main_image']): ?><img class="img-fluid rounded-4 shadow" src="<?=e($a['main_image'])?>" alt="<?=e($a['name'])?>"><?php else: ?><div class="hero rounded-4 p-5"><h2><?=e($a['name'])?></h2></div><?php endif; ?></div><div class="col-lg-6"><small class="text-success"><?=e($a['destination_name'])?></small><h1 class="display-serif"><?=e($a['name'])?></h1><p class="lead"><?=e($a['short_description'])?></p><p><?=nl2br(e($a['description']))?></p><dl><dt>Opening hours</dt><dd><?=e($a['opening_hours']?:'Please check locally')?></dd><dt>Entry information</dt><dd><?=e($a['entry_information']?:'See venue')?></dd></dl><?php if($a['maps_url']): ?><a target="_blank" rel="noopener" href="<?=e($a['maps_url'])?>" class="btn btn-success me-2"><i class="fa-solid fa-map"></i> View map</a><?php endif; ?><?php if(youtube_id($a['youtube_url'])): ?><a target="_blank" rel="noopener" href="<?=e($a['youtube_url'])?>" class="btn btn-outline-danger"><i class="fa-brands fa-youtube"></i> Watch video</a><?php endif; ?></div></div></main><?php include __DIR__.'/includes/footer.php'; ?>
